"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["13740"],{8281(e){e.exports=JSON.parse('{"id":"NEW-02","slug":"variance-statistics","term":"Variance (Statistics)","also_known_as":[],"difficulty":"Intermediate","definition":"Variance, in statistics, is a measure of how spread out a set of values is, calculated as the average of the squared differences between each value and the mean.","explanation":["Variance tells you how far, on average, values lie from their mean. A small variance means values are clustered tightly around the mean; a large variance means they are widely spread.","To calculate it, find the mean, subtract it from each value, square each difference, add the squares and divide. For the values 2, 4, 6 and 8, the mean is 5. The differences are \u22123, \u22121, 1 and 3, and their squares are 9, 1, 1 and 9, which add up to 20. Dividing by the number of values, 4, gives a population variance of 5. When the data are a sample from a larger population, statisticians usually divide by one less than the number of values, 3, giving a sample variance of about 6.67.","The differences are squared so that positive and negative deviations do not cancel out, and so that larger deviations count more heavily.","In finance, variance is used to measure the risk of investment returns. Because it is in squared units, which are hard to interpret, people usually look at its square root, the standard deviation. Variance is still important in portfolio theory, where the variances of individual assets and their covariances determine a portfolio\'s overall risk."],"note":"","total":1500,"prev":{"slug":"variable-rate","term":"Variable Rate"},"next":{"slug":"variation-margin","term":"Variation Margin"}}')}}]);